				(char *)authblob + sess_key_off, sess_key_len);
#if LINUX_VERSION_CODE >= KERNEL_VERSION(5, 9, 0)
		kfree_sensitive(ctx_arc4);
#else
		memzero_explicit((void *)ctx_arc4, sizeof(*ctx_arc4));
		kfree(ctx_arc4);
#endif
	}

	return ret;
}

