static bool decode(RArchSession *as, RAnalOp *op, RArchDecodeMask mask) {
	int len = op->size;
	const ut8 *_buf = op->bytes;
	const ut64 addr = op->addr;
	if (len < 1) {
		return false;
	}

	ut8 *buf = (ut8*)_buf; // XXX
	ut64 dst = 0LL;
	if (!op) {
		return 1;
	}
