						dst = addr + (size_t)(p - buf) + 1;
						op->jump = dst;
						r_strbuf_set (&op->esil, "1,pc,-,brk,=[4],4,brk,+=,");
						goto beach;
					}
				}
				if (*p == 0x00 || *p == 0xff) {
